\title{Exact First-Moment Identities for the Erd\H{o}s--R\'enyi Random Graph
$G(n,p)$ and the Combinatorial Origin of Threshold Phenomena}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}

\begin{abstract}
We develop, from first principles, the exact first-moment theory of the
Erd\H{o}s--R\'enyi random graph $G(n,p)$ on a fixed labelled vertex set, and we
exhibit how the three classical thresholds of the model---the connectivity
threshold at $p = \ln n / n$, the giant-component / triangle-appearance
transition at $p = 1/n$, and the appearance thresholds of fixed subgraphs---all
descend from a single linearity-of-expectation identity evaluated on three
different families of events. Concretely, we prove (i) a general counting
identity $\E[\#\{i\in I : g \in A_i\}] = \sum_{i\in I}\Prob(A_i)$ with no
independence hypothesis; (ii) the combinatorial cardinalities
$|\Edge(n)| = \binom{n}{2}$, $|\incident(v)| = n-1$, and $|\triEdges(T)| = 3$ for
$|T|=3$; and (iii) the three exact expectations $\E[\#\text{edges}] =
\binom{n}{2}p$, $\E[\#\text{isolated vertices}] = n(1-p)^{n-1}$, and
$\E[\#\text{triangles}] = \binom{n}{3}p^3$. We explain how these exact identities
feed the first- and second-moment methods to localize each threshold, state the
asymptotic threshold theorems as corollaries-in-waiting, and record the open
conjectures that the present exact machinery makes tractable.
\end{abstract}

\maketitle

\section{Introduction}

The random graph model $G(n,p)$ of Erd\H{o}s and R\'enyi (1959) assigns,
independently and with probability $p$, an edge to each of the $\binom{n}{2}$
pairs of a fixed set of $n$ labelled vertices. Despite its disarming simplicity,
$G(n,p)$ is the canonical setting in which to study \emph{threshold phenomena}:
monotone graph properties that, as $p$ increases through a critical scale, switch
from ``almost surely false'' to ``almost surely true'' within a vanishingly
narrow window. The three landmark examples are:
\begin{enumerate}
  \item \textbf{Connectivity}, with sharp threshold $p = \ln n / n$;
  \item \textbf{The giant component}, a phase transition at $p = 1/n$;
  \item \textbf{Appearance of a fixed subgraph $H$}, with threshold
    $p = n^{-1/m(H)}$, where $m(H)$ is the maximum edge-to-vertex density of a
    subgraph of $H$ (for a triangle, $m(K_3)=1$, giving threshold $1/n$).
\end{enumerate}

The unifying methodological insight---the \emph{moment method}---is that these
qualitative transitions are governed quantitatively by the first two moments of
natural counting statistics. The purpose of this paper is to isolate and prove
the \emph{exact, finite-$n$ first-moment identities} at the foundation of the
theory, to make explicit the single linear identity from which they all flow, and
to delineate precisely how far the first moment alone determines each threshold
and where the second moment must take over.

\section{The model}

Throughout, $n \in \mathbb{N}$ and $p \in [0,1]$ (formally $p \in \mathbb{R}$;
the identities below are polynomial in $p$).

\begin{definition}[Configuration space and edges]
Fix the vertex set $V = \{0,1,\dots,n-1\}$. The set of \emph{potential edges} is
\[
  \Edge(n) = \{\, (i,j) \in V \times V : i < j \,\}.
\]
A \emph{configuration} is a Boolean assignment $g : \Edge(n) \to
\{\mathtt{true},\mathtt{false}\}$, where $g(e)=\mathtt{true}$ means edge $e$ is
present. The Erd\H{o}s--R\'enyi law is the product Bernoulli$(p)$ measure on
configurations: edges are present independently, each with probability $p$.
\end{definition}

\begin{definition}[Expectation and probability]
For a real functional $f$ of the configuration, $\E_p[f]$ denotes its expectation
under the product Bernoulli$(p)$ law. For an event $A$ (a set of configurations),
$\Prob_p(A)$ is its probability.
\end{definition}

\begin{definition}[Present / absent events]
For a set of edges $S \subseteq \Edge(n)$, let $\allPresent(S)$ be the event
``every edge of $S$ is present'' and $\allAbsent(S)$ the event ``every edge of
$S$ is absent''. By edge independence,
\begin{equation}\label{eq:product}
  \Prob_p(\allPresent(S)) = p^{|S|}, \qquad
  \Prob_p(\allAbsent(S)) = (1-p)^{|S|}.
\end{equation}
\end{definition}

\begin{definition}[Subgraph count]
Given a family of edge-sets $(S_i)$, $\subgraphCount$ counts how many of the
corresponding copies are fully present in a configuration. Its first moment is
$\E_p[\subgraphCount] = \sum_i p^{|S_i|}$, an immediate consequence of
\eqref{eq:product} and linearity.
\end{definition}

\section{The master identity}

\begin{theorem}[Linearity of expectation for counts]\label{thm:count}
Let $I$ be a finite index set and $(A_i)_{i \in I}$ a family of events. Define the
count $X(g) = \#\{\, i \in I : g \in A_i \,\}$. Then
\[
  \E_p[X] = \sum_{i \in I} \Prob_p(A_i).
\]
\end{theorem}

\begin{proof}[Proof sketch]
Write $X(g) = \sum_{i\in I} \mathbf{1}[g \in A_i]$ as a sum of indicators.
Expectation is a finite linear functional over the configuration space (a
weighted finite sum over configurations), so it commutes with the finite sum over
$i$: $\E_p[X] = \sum_{i\in I} \E_p[\mathbf{1}[\cdot \in A_i]] = \sum_{i \in
I}\Prob_p(A_i)$. Formally this is an exchange of two finite sums (Fubini for
finite sums) after expanding the filtered cardinality as a sum of indicators. No
property of the measure beyond linearity is used; in particular the events $A_i$
need not be independent.
\end{proof}

Theorem~\ref{thm:count} is the only probabilistic input we need. Every
expectation below is Theorem~\ref{thm:count} specialized to a particular event
family; the only additional work is one probability via \eqref{eq:product} and
one cardinality.

\section{Edges}

\begin{lemma}[Number of potential edges]\label{lem:edge}
$|\Edge(n)| = \binom{n}{2}$.
\end{lemma}

\begin{proof}[Proof sketch]
$\Edge(n)$ is the subtype of pairs $(i,j)$ with $i<j$. Counting by the larger
coordinate, the number of pairs with second coordinate $j$ is $j$, so the total
is $\sum_{j=0}^{n-1} j = \binom{n}{2}$ (Gauss's sum).
\end{proof}

\begin{theorem}[Expected number of edges]\label{thm:edges}
$\E_p[\#\text{edges}] = \binom{n}{2}\, p.$
\end{theorem}

\begin{proof}[Proof sketch]
The edge count is the subgraph count for the singleton family $e \mapsto \{e\}$,
each copy having $|S|=1$. By the subgraph-count first moment (equivalently
Theorem~\ref{thm:count} with $A_e = \allPresent(\{e\})$ and \eqref{eq:product}),
the expectation is $\sum_{e}p = |\Edge(n)|\cdot p = \binom{n}{2}p$ by
Lemma~\ref{lem:edge}.
\end{proof}

\section{Isolated vertices and the connectivity threshold}

\begin{definition}[Incident edges]
For a vertex $v$, $\incident(v) = \{\, e \in \Edge(n) : v \text{ is an endpoint of
} e \,\}$.
\end{definition}

\begin{lemma}[Degree of the complete graph]\label{lem:incident}
For every vertex $v$, $|\incident(v)| = n-1.$
\end{lemma}

\begin{proof}[Proof sketch]
The map sending an incident edge to its \emph{other} endpoint is a bijection
between $\incident(v)$ and $V \setminus \{v\}$; explicitly, $u \mapsto (u,v)$ if
$u<v$ and $u\mapsto (v,u)$ otherwise is an injection from the $n-1$ vertices
$u \neq v$ onto $\incident(v)$.
\end{proof}

\begin{theorem}[Expected number of isolated vertices]\label{thm:iso}
A vertex is \emph{isolated} when all of its incident edges are absent. Then
\[
  \E_p[\#\text{isolated vertices}] = n\,(1-p)^{\,n-1}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:count} with index set $I = V$ and events $A_v =
\allAbsent(\incident(v))$. By \eqref{eq:product}, $\Prob_p(A_v) =
(1-p)^{|\incident(v)|} = (1-p)^{n-1}$ using Lemma~\ref{lem:incident}. Summing over
the $n$ vertices gives $n(1-p)^{n-1}$.
\end{proof}

\begin{corollary}[Sharp connectivity threshold; asymptotic, stated for context]
Let $X_n$ be the number of isolated vertices in $G(n,p_n)$ with $p_n = (\ln n +
c)/n$. From Theorem~\ref{thm:iso}, $\E[X_n] = n(1-p_n)^{n-1} \to e^{-c} > 0$.
Combined with a second-moment estimate showing $\Var(X_n)/\E[X_n]^2 \to 0$, the
second-moment method yields disconnection with probability $\to 1 - e^{-e^{-c}}$
as $c \to -\infty$ and connection with probability $\to 1$ as $c \to +\infty$;
the sharp threshold sits at $p = \ln n / n$. The factor $\ln n$ is exactly the
value making $n(1-p)^{n-1}$ tend to a positive constant. (In the present
development the exact mean is proved; the covariance estimate is
Conjecture~\ref{conj:C1}.)
\end{corollary}

\section{Triangles and the appearance threshold}

\begin{definition}[Edges spanned by a vertex set]
For $T \subseteq V$, $\triEdges(T) = \{\, e \in \Edge(n) : \text{both endpoints of
} e \text{ lie in } T \,\}$.
\end{definition}

\begin{lemma}[A triple spans three edges]\label{lem:tri}
If $|T| = 3$ then $|\triEdges(T)| = 3.$
\end{lemma}

\begin{proof}[Proof sketch]
The map $e \mapsto \{e_1, e_2\}$ (the unordered endpoint pair) is a bijection from
$\triEdges(T)$ onto the $2$-element subsets of $T$, of which there are
$\binom{3}{2} = 3$.
\end{proof}

\begin{theorem}[Expected number of triangles]\label{thm:tri}
Triangles are indexed by $3$-element vertex subsets; a triple $T$ forms a triangle
when all of $\triEdges(T)$ are present. Then
\[
  \E_p[\#\text{triangles}] = \binom{n}{3}\, p^{3}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
Apply Theorem~\ref{thm:count} with index set the $3$-subsets of $V$ (of which
there are $\binom{n}{3}$) and events $A_T = \allPresent(\triEdges(T))$. By
\eqref{eq:product} and Lemma~\ref{lem:tri}, $\Prob_p(A_T) = p^{|\triEdges(T)|} =
p^{3}$ for every such $T$. Summing the constant $p^3$ over the $\binom{n}{3}$
triples gives $\binom{n}{3}p^3$.
\end{proof}

\begin{corollary}[Triangle / giant-component scale; asymptotic, for context]
Since $\binom{n}{3} \sim n^3/6$, Theorem~\ref{thm:tri} gives
$\E[\#\text{triangles}] \sim \tfrac{1}{6}(np)^3$. If $np \to 0$ the first moment
$\to 0$ and Markov's inequality forces $\#\text{triangles} = 0$ whp; if $np \to
\infty$ the second-moment method forces $\#\text{triangles} \ge 1$ whp. Hence
triangles appear at threshold $p = 1/n$, the same scale at which the giant
component emerges.
\end{corollary}

\section{The two-sided moment method}

Let $X \ge 0$ be an integer-valued count.
\begin{itemize}
  \item \textbf{First-moment (Markov) bound.} $\Prob(X \ge 1) \le \E[X]$; thus
    $\E[X] \to 0$ implies $X = 0$ whp. This handles the \emph{disappearance} side
    of every threshold.
  \item \textbf{Second-moment bound.} If $\Var(X)/\E[X]^2 \to 0$ then $X > 0$
    whp. This handles the \emph{appearance} side, provided the variance is
    controlled.
\end{itemize}
The exact identities of the preceding sections supply the means $\E[X]$ that
decide the first-moment side outright. The second-moment side reduces to finite
sums over pairs of copies graded by their edge overlap, where
\eqref{eq:product} again gives each joint probability exactly as
$p^{|S'\cup S''|}$.

\section{Open problems and future directions}

\begin{conjecture}[Sharp connectivity via the second moment of isolated vertices]
\label{conj:C1}
With $p_n = (\ln n + c)/n$, $\Var(X_n)/\E[X_n]^2 \to 0$ for the isolated-vertex
count $X_n$. Combined with $\E[X_n] \to e^{-c}$ (Theorem~\ref{thm:iso}), this
yields disconnection probability $\to 1 - e^{-e^{-c}}$ and the sharp threshold
$p = \ln n / n$.
\end{conjecture}

\begin{conjecture}[Variance of subgraph counts factors over edge overlaps]
For a fixed graph $H$ with $e_H$ edges, the count $X_H$ of copies satisfies
\[
  \Var(X_H) = \sum_{H',H''} \bigl(p^{|E(H')\cup E(H'')|} - p^{2e_H}\bigr),
\]
summed over ordered pairs of copies, the dominant contribution coming from pairs
sharing at least one edge.
\end{conjecture}

\begin{conjecture}[Appearance threshold $p = n^{-1/m(H)}$]
For a fixed connected $H$ with $m(H) = \max_{H'\subseteq H} |E(H')|/|V(H')|$,
copies of $H$ vanish below $n^{-1/m(H)}$ and appear above it.
\end{conjecture}

\begin{conjecture}[Poisson limit for triangles at criticality]
At $p_n = c/n$, the triangle count $T_n$ converges in distribution to
$\mathrm{Poisson}(c^3/6)$; the mean $\binom{n}{3}p_n^3 \to c^3/6$ is precisely
Theorem~\ref{thm:tri} evaluated at $p_n = c/n$.
\end{conjecture}

\section{Conclusion}

The first-moment foundations of Erd\H{o}s--R\'enyi threshold theory collapse to a
single identity---linearity of expectation for counts
(Theorem~\ref{thm:count})---applied to three event families, with the only
combinatorial inputs being three cardinalities ($\binom{n}{2}$, $n-1$, $3$). The
resulting exact means $\binom{n}{2}p$, $n(1-p)^{n-1}$, and $\binom{n}{3}p^3$
localize, respectively, the density of the graph, the connectivity threshold
$\ln n / n$, and the triangle / giant-component scale $1/n$. The symmetry between
present-events and absent-events is exactly the duality $p^{|S|} \leftrightarrow
(1-p)^{|S|}$ of \eqref{eq:product}. What remains for the full asymptotic theorems
are the matching second-moment estimates, which the present exact framework
reduces to finite, overlap-graded sums.

