function expected_count(p, index_set I, event_size: I -> Nat, present: Bool):
    total <- 0
    for i in I:
        s <- event_size(i)            # |S_i|, a cardinality
        if present:
            prob_i <- p ** s          # P(allPresent S_i)
        else:
            prob_i <- (1 - p) ** s     # P(allAbsent S_i)
        total <- total + prob_i
    return total                       # = E[# events that occur]

function locate_threshold(mean_fn, n, p_lo, p_hi, grid):
    prev_p <- p_lo
    for p in logspace(p_lo, p_hi, grid):
        mu <- mean_fn(n, p)
        if mu_was_small and mu >= 1:
            return geometric_midpoint(prev_p, p)   # crossover scale
        mu_was_small <- (mu < 1)
        prev_p <- p
    return None
